def handle(query, state):
    """
    A command injection vulnerability through input passed to a shell command.
    The query parameter is unsanitized and interpolated into a command string
    that gets executed, allowing arbitrary command execution via pipe injection.
    """
    vfs = state.get('files', {})

    def run_cmd(argv):
        """Execute a command from argv list against virtual filesystem."""
        if not argv:
            return ''
        cmd = argv[0]
        args = argv[1:]

        if cmd == 'echo':
            return ' '.join(args)
        elif cmd == 'cat':
            out = ''
            for path in args:
                content = vfs.get(path)
                if content is None:
                    out += f'cat: {path}: No such file or directory'
                else:
                    out += content
            return out
        elif cmd == 'grep':
            if len(args) < 2:
                return 'grep: usage: grep pattern file'
            pattern = args[0]
            filepath = args[1]
            content = vfs.get(filepath, '')
            out = ''
            for line in content.split('\n'):
                if pattern in line:
                    out += line + '\n'
            return out.rstrip('\n')
        elif cmd == 'ls':
            path = args[0] if args else '/'
            path = path.rstrip('/')
            entries = set()
            for fp in vfs:
                if fp.startswith(path + '/'):
                    remainder = fp[len(path) + 1:]
                    top = remainder.split('/')[0]
                    entries.add(top)
            return '\n'.join(sorted(entries)) if entries else ''
        elif cmd == 'whoami':
            return 'user'
        else:
            return f'{cmd}: command not found'

    def shell_exec_with_pipes(cmdline):
        """Execute shell command with pipe operator support.
        Split on pipe and chain command outputs."""
        segments = cmdline.split('|')
        output = ''

        for segment in segments:
            segment = segment.strip()
            if not segment:
                continue
            argv = segment.split()
            if argv:
                output = run_cmd(argv)

        return output

    query_param = (query.get('q') or [''])[0]
    if not query_param:
        body = 'Usage: ?q=<query>'
        return 200, {'Content-Type': 'text/plain'}, body

    # Vulnerable: query_param is embedded directly in the command string
    # An attacker can inject arbitrary commands using pipe operator
    cmd = f'echo Results for {query_param}'
    output = shell_exec_with_pipes(cmd)

    body = (
        '<html><head><title>Query</title></head><body>'
        '<h1>Search Results</h1>'
        f'<p>Query: <code>{query_param}</code></p>'
        '<pre>' + output + '</pre>'
        '</body></html>'
    )
    return 200, {'Content-Type': 'text/html'}, body
